import{_ as a,o as s,c as t,a6 as r}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"Performance and bounded work","description":"","frontmatter":{"title":"Performance and bounded work","docId":"developer.performance","translationKey":"developer.performance","locale":"en","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"04bc0a89b86724872adae3ab8ddc8e29f5517dad14d51bc103d917582cf289ae","translationRevision":"04bc0a89b86724872adae3ab8ddc8e29f5517dad14d51bc103d917582cf289ae","order":110},"headers":[],"relativePath":"en/developer/performance.md","filePath":"en/developer/performance.md","lastUpdated":1794591482000}'),n={name:"en/developer/performance.md"};function i(o,e,d,l,c,p){return s(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="performance-and-bounded-work" tabindex="-1">Performance and bounded work <a class="header-anchor" href="#performance-and-bounded-work" aria-label="Permalink to &quot;Performance and bounded work {#performance-and-bounded-work}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Measure a concrete bottleneck while preserving event accounting and shutdown. Start with a fixed build, deterministic input and an isolated profile. Read <a href="./events.html">events</a> so a faster feed is not confused with more reliable persistence. Historical benchmark numbers are observations of their named build and machine, not current product guarantees.</p><h2 id="measure-the-right-boundary" tabindex="-1">Measure the right boundary <a class="header-anchor" href="#measure-the-right-boundary" aria-label="Permalink to &quot;Measure the right boundary {#measure-the-right-boundary}&quot;">​</a></h2><p>The desktop outbox separates lossy presentation from reliable responses. Snapshots can coalesce; reliable overflow must fail visibly. LIVE ingress, plugin work, processor calls and automation admission each have their own bounds. Increasing one queue can move memory pressure or latency into the next stage.</p><p>The frontend runtime exposes aggregate diagnostics in development or when built with <code>VITE_TIKTOOLS_DIAGNOSTICS=1</code>. Its snapshot includes rendered rows, frame-interval percentiles, control-client pending calls, images and owned timers. JavaScript heap data can be unavailable on a particular WebView. Hidden pages and host visibility govern presentation interest, not business accounting.</p><h2 id="run-a-focused-comparison" tabindex="-1">Run a focused comparison <a class="header-anchor" href="#run-a-focused-comparison" aria-label="Permalink to &quot;Run a focused comparison {#run-a-focused-comparison}&quot;">​</a></h2><ol><li>Record build revision, platform, event mix, images enabled, visible tab and duration.</li><li>Establish a baseline with the same fixture and sample period.</li><li>Change one boundary, then compare throughput, p95/p99 latency, queue drops, gaps, retained memory and shutdown drain behavior.</li><li>Include a slow plugin or consumer and a saturated queue; an idle benchmark does not test backpressure.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live-feed-state</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --features</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persistence,native-tiktok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> live_throughput</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>Inspect feature requirements before enabling a native benchmark; ordinary focused unit checks need no real TikTok connection. Use <code>crates/tiktools-core/tests/live_throughput.rs</code> and the desktop outbox tests as implementation references.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Bounded projection and admission paths are implemented, with counters and gap reporting. The <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/services/points/queue.rs" target="_blank" rel="noreferrer">current ordered writer</a> rejects saturated writes before changing memory and forbids synchronous write fallback. Older performance reports describe superseded ordering defects. Assess cache bounds and failure recovery against current implementation/tests rather than infer complete correctness from bounded UI memory.</p><h2 id="recover" tabindex="-1">Recover <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;Recover {#recover}&quot;">​</a></h2><p>If frames improve while accounting health degrades, revert the boundary change and inspect writer/admission outcomes. If hidden-tab timers grow, follow <a href="./lifecycle.html">lifecycle cleanup</a>. Keep raw input count, accepted count and loss classification in the report. A gap can recover display state; it cannot repair an effect that was rejected or became uncertain.</p>`,14)])])}const m=a(n,[["render",i]]);export{u as __pageData,m as default};
